// Nonlinear MPC for the quadrotor, solved with the acados code generated by
// nmpc/generate_solver.py (SQP real-time iteration, 20 steps of 50 ms).
//
// Every control period (100 Hz):
//   1. the measured state [p, v, q] is the initial-state constraint;
//   2. the reference is sampled at t, t + 50 ms, ..., t + 1 s; at each node the reference
//      attitude and thrust come from the reference acceleration (differential flatness);
//   3. one SQP-RTI iteration gives the first input u0 = (thrust, body rates), published on
//      /quad/cmd/rates_thrust, the same interface as the cascaded controller.
// A disturbance observer estimates the external acceleration (wind, unmodelled payload) from
// the measured and predicted velocity change and passes it to the model as a parameter, which
// gives offset-free tracking.
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <memory>

#include <Eigen/Dense>
#include <nav_msgs/msg/odometry.hpp>
#include <nav_msgs/msg/path.hpp>
#include <rclcpp/rclcpp.hpp>
#include <std_msgs/msg/float64_multi_array.hpp>
#include <std_srvs/srv/set_bool.hpp>

#include "quad_control/reference.hpp"
#include "quad_interfaces/msg/rates_thrust.hpp"
#include "quad_interfaces/msg/reference_trajectory.hpp"

extern "C" {
#include "acados_c/ocp_nlp_interface.h"
#include "acados_solver_quadrotor.h"
}

namespace
{
using quad_control::kGravity;
constexpr int N = QUADROTOR_N;
constexpr int NX = QUADROTOR_NX;
constexpr int NU = QUADROTOR_NU;
constexpr int NY = QUADROTOR_NY;
constexpr int NP = QUADROTOR_NP;
constexpr double kStepDt = 0.05;  // must match DT in generate_solver.py
}  // namespace

class NmpcController : public rclcpp::Node
{
public:
  NmpcController() : Node("nmpc_controller")
  {
    mass_ = declare_parameter("mass", 0.5);
    rate_hz_ = declare_parameter("rate_hz", 100.0);
    thrust_min_ = declare_parameter("thrust_min", 0.5);
    thrust_max_ = declare_parameter("thrust_max", 2.0 * mass_ * kGravity);
    const auto max_rate = declare_parameter("max_rate", std::vector<double>{6.0, 6.0, 3.0});
    use_observer_ = declare_parameter("disturbance_observer", true);
    observer_tau_ = declare_parameter("observer_time_constant", 0.3);
    max_disturbance_ = declare_parameter("max_disturbance", 4.0);

    capsule_ = quadrotor_acados_create_capsule();
    if (quadrotor_acados_create(capsule_) != 0) {
      throw std::runtime_error("acados solver creation failed");
    }
    config_ = quadrotor_acados_get_nlp_config(capsule_);
    dims_ = quadrotor_acados_get_nlp_dims(capsule_);
    in_ = quadrotor_acados_get_nlp_in(capsule_);
    out_ = quadrotor_acados_get_nlp_out(capsule_);
    solver_ = quadrotor_acados_get_nlp_solver(capsule_);

    double lbu[NU] = {thrust_min_, -max_rate.at(0), -max_rate.at(1), -max_rate.at(2)};
    double ubu[NU] = {thrust_max_, max_rate.at(0), max_rate.at(1), max_rate.at(2)};
    for (int k = 0; k < N; ++k) {
      ocp_nlp_constraints_model_set(config_, dims_, in_, out_, k, "lbu", lbu);
      ocp_nlp_constraints_model_set(config_, dims_, in_, out_, k, "ubu", ubu);
    }
    setParameters();

    odom_sub_ = create_subscription<nav_msgs::msg::Odometry>(
      "/quad/odom", rclcpp::SensorDataQoS(), [this](const nav_msgs::msg::Odometry::SharedPtr m) { onOdom(*m); });
    ref_sub_ = create_subscription<quad_interfaces::msg::ReferenceTrajectory>(
      "/quad/reference", 10,
      [this](const quad_interfaces::msg::ReferenceTrajectory::SharedPtr m) { ref_.set(*m); });
    cmd_pub_ = create_publisher<quad_interfaces::msg::RatesThrust>("/quad/cmd/rates_thrust", rclcpp::SensorDataQoS());
    diag_pub_ = create_publisher<std_msgs::msg::Float64MultiArray>("/quad/nmpc/diagnostics", 10);
    path_pub_ = create_publisher<nav_msgs::msg::Path>("/quad/nmpc/predicted_path", 10);
    enable_srv_ = create_service<std_srvs::srv::SetBool>(
      "/quad/controller/enable",
      [this](const std_srvs::srv::SetBool::Request::SharedPtr req, std_srvs::srv::SetBool::Response::SharedPtr res) {
        enabled_ = req->data;
        disturbance_.setZero();
        setParameters();
        quadrotor_acados_reset(capsule_, 1, 1, 0, 1);
        res->success = true;
        res->message = enabled_ ? "NMPC enabled" : "NMPC disabled";
        RCLCPP_INFO(get_logger(), "%s", res->message.c_str());
      });
    timer_ = rclcpp::create_timer(this, get_clock(), rclcpp::Duration::from_seconds(1.0 / rate_hz_),
                                  [this] { update(); });
    RCLCPP_INFO(get_logger(), "NMPC ready: N = %d, dt = %.0f ms, thrust %.1f-%.1f N, observer %s", N,
                kStepDt * 1e3, thrust_min_, thrust_max_, use_observer_ ? "on" : "off");
  }

  ~NmpcController() override
  {
    quadrotor_acados_free(capsule_);
    quadrotor_acados_free_capsule(capsule_);
  }

private:
  void setParameters()
  {
    double p[NP] = {mass_, disturbance_.x(), disturbance_.y(), disturbance_.z()};
    for (int k = 0; k <= N; ++k) {
      quadrotor_acados_update_params(capsule_, k, p, NP);
    }
  }

  void onOdom(const nav_msgs::msg::Odometry & m)
  {
    const auto & P = m.pose.pose;
    p_ = {P.position.x, P.position.y, P.position.z};
    q_ = Eigen::Quaterniond(P.orientation.w, P.orientation.x, P.orientation.y, P.orientation.z).normalized();
    const auto & T = m.twist.twist.linear;
    v_ = q_ * Eigen::Vector3d(T.x, T.y, T.z);  // body -> world
    const double t = rclcpp::Time(m.header.stamp).seconds();

    // Disturbance observer: low-pass of (measured - predicted) acceleration, with the
    // last commanded thrust. Only in flight: on the ground the contact force is not a
    // disturbance.
    if (use_observer_ && enabled_ && have_odom_ && last_thrust_ > 0.0 && p_.z() > ground_z_ + 0.15) {
      const double dt = t - t_prev_;
      if (dt > 1e-4 && dt < 0.1) {
        const Eigen::Vector3d a_meas = (v_ - v_prev_) / dt;
        const Eigen::Vector3d a_model =
          last_thrust_ / mass_ * (q_ * Eigen::Vector3d::UnitZ()) - Eigen::Vector3d(0.0, 0.0, kGravity);
        const double alpha = dt / (observer_tau_ + dt);
        disturbance_ += alpha * (a_meas - a_model - disturbance_);
        const double n = disturbance_.norm();
        if (n > max_disturbance_) {
          disturbance_ *= max_disturbance_ / n;
        }
      }
    }
    if (!have_odom_) {
      ground_z_ = p_.z();
    }
    v_prev_ = v_;
    t_prev_ = t;
    have_odom_ = true;
  }

  void update()
  {
    if (!enabled_ || !have_odom_ || !ref_.valid()) {
      return;
    }
    setParameters();

    // Initial state; keep the quaternion in the hemisphere of the previous one.
    Eigen::Quaterniond q = q_;
    double x0[NX] = {p_.x(), p_.y(), p_.z(), v_.x(), v_.y(), v_.z(), q.w(), q.x(), q.y(), q.z()};
    ocp_nlp_constraints_model_set(config_, dims_, in_, out_, 0, "lbx", x0);
    ocp_nlp_constraints_model_set(config_, dims_, in_, out_, 0, "ubx", x0);

    // References at the shooting nodes.
    const double t0 = now().seconds();
    Eigen::Vector4d q_prev(q.w(), q.x(), q.y(), q.z());
    nav_msgs::msg::Path path;
    for (int k = 0; k <= N; ++k) {
      const quad_control::RefPoint r = ref_.at(t0 + k * kStepDt);
      const Eigen::Vector3d acc = r.a + Eigen::Vector3d(0.0, 0.0, kGravity) - disturbance_;
      const Eigen::Quaterniond qr(quad_control::attitudeFromAcceleration(acc, r.yaw));
      Eigen::Vector4d qv(qr.w(), qr.x(), qr.y(), qr.z());
      if (qv.dot(q_prev) < 0.0) {
        qv = -qv;  // q and -q are the same rotation; the cost compares components
      }
      q_prev = qv;
      double y[NY] = {r.p.x(), r.p.y(), r.p.z(), r.v.x(), r.v.y(), r.v.z(), qv(0), qv(1), qv(2), qv(3),
                      std::clamp(mass_ * acc.norm(), thrust_min_, thrust_max_), 0.0, 0.0, 0.0};
      ocp_nlp_cost_model_set(config_, dims_, in_, k, "yref", y);  // NX values at k = N
    }

    const auto start = std::chrono::steady_clock::now();
    const int status = quadrotor_acados_solve(capsule_);
    const double solve_ms =
      std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();

    double u0[NU];
    ocp_nlp_out_get(config_, dims_, out_, 0, "u", u0);
    if (status != 0 || !std::isfinite(u0[0])) {
      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 1000, "acados status %d: solver reset", status);
      quadrotor_acados_reset(capsule_, 1, 1, 0, 1);
      if (!std::isfinite(u0[0])) {
        return;  // the driver's failsafe takes over if this persists
      }
    }

    quad_interfaces::msg::RatesThrust cmd;
    cmd.header.stamp = now();
    cmd.header.frame_id = "base_link";
    cmd.thrust = u0[0];
    cmd.body_rates.x = u0[1];
    cmd.body_rates.y = u0[2];
    cmd.body_rates.z = u0[3];
    cmd_pub_->publish(cmd);
    last_thrust_ = u0[0];

    std_msgs::msg::Float64MultiArray diag;
    diag.data = {solve_ms, static_cast<double>(status), disturbance_.x(), disturbance_.y(), disturbance_.z()};
    diag_pub_->publish(diag);

    if (++path_count_ % 10 == 0) {  // predicted positions, 10 Hz, for RViz
      path.header.stamp = cmd.header.stamp;
      path.header.frame_id = "odom";
      for (int k = 0; k <= N; ++k) {
        double xk[NX];
        ocp_nlp_out_get(config_, dims_, out_, k, "x", xk);
        geometry_msgs::msg::PoseStamped ps;
        ps.header = path.header;
        ps.pose.position.x = xk[0];
        ps.pose.position.y = xk[1];
        ps.pose.position.z = xk[2];
        ps.pose.orientation.w = 1.0;
        path.poses.push_back(ps);
      }
      path_pub_->publish(path);
    }
  }

  // acados
  quadrotor_solver_capsule * capsule_{nullptr};
  ocp_nlp_config * config_{nullptr};
  ocp_nlp_dims * dims_{nullptr};
  ocp_nlp_in * in_{nullptr};
  ocp_nlp_out * out_{nullptr};
  ocp_nlp_solver * solver_{nullptr};

  double mass_, rate_hz_, thrust_min_, thrust_max_, observer_tau_, max_disturbance_;
  bool use_observer_{true}, enabled_{true}, have_odom_{false};
  Eigen::Vector3d p_{Eigen::Vector3d::Zero()}, v_{Eigen::Vector3d::Zero()}, v_prev_{Eigen::Vector3d::Zero()};
  Eigen::Vector3d disturbance_{Eigen::Vector3d::Zero()};
  Eigen::Quaterniond q_{Eigen::Quaterniond::Identity()};
  double t_prev_{0.0}, last_thrust_{0.0}, ground_z_{0.0};
  unsigned path_count_{0};
  quad_control::ReferenceBuffer ref_;

  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr odom_sub_;
  rclcpp::Subscription<quad_interfaces::msg::ReferenceTrajectory>::SharedPtr ref_sub_;
  rclcpp::Publisher<quad_interfaces::msg::RatesThrust>::SharedPtr cmd_pub_;
  rclcpp::Publisher<std_msgs::msg::Float64MultiArray>::SharedPtr diag_pub_;
  rclcpp::Publisher<nav_msgs::msg::Path>::SharedPtr path_pub_;
  rclcpp::Service<std_srvs::srv::SetBool>::SharedPtr enable_srv_;
  rclcpp::TimerBase::SharedPtr timer_;
};

int main(int argc, char ** argv)
{
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<NmpcController>());
  rclcpp::shutdown();
  return 0;
}
